package com.jmadsen.dashhop;
import android.Manifest;import android.app.*;import android.content.pm.PackageManager;import android.location.*;import android.os.*;import android.widget.*;import org.json.*;import java.util.*;
final class WeatherSetup {
 final DockSettingsActivity c;final ShortcutRepository r;LocationManager manager;LocationListener listener;final Handler h=new Handler(Looper.getMainLooper());
 WeatherSetup(DockSettingsActivity c){this.c=c;r=c.repo;}
 void add(){c.section("Weather");c.choice("API access","weatherAccess",new String[]{"evaluation","commercial"},new String[]{"Noncommercial evaluation","Licensed commercial API key"},"evaluation");c.button("Set commercial weather API key",()->{EditText key=new EditText(c);key.setHint("Your Open-Meteo customer API key");key.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);new AlertDialog.Builder(c).setTitle("Licensed weather access").setMessage("Use an API key covered by your provider agreement. Stored privately on this unit, excluded from logs/backups. No key is shipped with DashHopper.").setView(key).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{r.set("weatherApiKey",key.getText().toString().trim());r.set("weatherCredentialRevision",r.num("weatherCredentialRevision",0)+1);c.build();}).show();});c.body.addView(c.label("Location: "+r.str("weatherPlace","Not configured")+"\nDirect weather uses head-unit internet. Phone weather is a future source. Evaluation is for noncommercial use; commercial use needs your licensed key.",14));c.choice("Source","weatherSource",new String[]{"direct","phone"},new String[]{"Direct Open-Meteo","Phone (not connected)"},"direct");c.choice("Temperature units","weatherUnits",new String[]{"f","c"},new String[]{"Fahrenheit","Celsius"},"f");c.button("Choose city",this::city);c.button("Enter coordinates",this::coordinates);c.button("Use device location (optional permission)",this::deviceLocation);c.button("Refresh weather now",()->{WeatherRepository.get(c).refresh(true);Toast.makeText(c,"Refresh requested; open the weather popup for status",Toast.LENGTH_LONG).show();});c.body.addView(c.label("Weather: Open-Meteo, CC BY 4.0. Location search: GeoNames via Open-Meteo. Free API is for noncommercial evaluation; review commercial licensing before distribution.",13));}
 void select(double lat,double lon,String name){try{DirectOpenMeteoProvider.coordinates(lat,lon);r.prefs.edit().putString("weatherLat",Double.toString(lat)).putString("weatherLon",Double.toString(lon)).putString("weatherPlace",name).apply();Diagnostics.info("weather_location_configured");c.build();}catch(Exception e){Toast.makeText(c,"Use latitude −90 to 90 and longitude −180 to 180",Toast.LENGTH_LONG).show();}}
 void city(){EditText query=new EditText(c);query.setHint("City or postal code");new AlertDialog.Builder(c).setTitle("Weather location").setView(query).setNegativeButton("Cancel",null).setPositiveButton("Search",(d,w)->{String q=query.getText().toString().trim();if(q.length()<2){Toast.makeText(c,"Enter at least two characters",Toast.LENGTH_SHORT).show();return;}Toast.makeText(c,"Searching…",Toast.LENGTH_SHORT).show();WeatherRepository.get(c).worker.execute(()->{try{JSONArray results=DirectOpenMeteoProvider.cities(q,r.str("weatherAccess","evaluation").equals("commercial"),r.str("weatherApiKey",""));c.runOnUiThread(()->{if(c.isFinishing()||c.isDestroyed())return;if(results==null||results.length()==0){Toast.makeText(c,"No matches; try coordinates",Toast.LENGTH_LONG).show();return;}String[] labels=new String[results.length()];for(int i=0;i<labels.length;i++){JSONObject x=results.optJSONObject(i);labels[i]=x.optString("name")+", "+x.optString("admin1")+", "+x.optString("country");}new AlertDialog.Builder(c).setTitle("Choose a location").setItems(labels,(dialog,index)->{JSONObject x=results.optJSONObject(index);select(x.optDouble("latitude"),x.optDouble("longitude"),labels[index]);}).setNegativeButton("Cancel",null).show();});}catch(Exception e){Diagnostics.error("weather_city_search_failed",e);c.runOnUiThread(()->{if(!c.isFinishing()&&!c.isDestroyed())Toast.makeText(c,"Location search unavailable; use coordinates",Toast.LENGTH_LONG).show();});}});}).show();}
 void coordinates(){LinearLayout fields=new LinearLayout(c);fields.setOrientation(1);EditText lat=new EditText(c),lon=new EditText(c),name=new EditText(c);lat.setHint("Latitude");lon.setHint("Longitude");name.setHint("Place label (optional)");lat.setText(r.str("weatherLat",""));lon.setText(r.str("weatherLon",""));for(EditText field:new EditText[]{lat,lon}){field.setSingleLine(true);field.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL|android.text.InputType.TYPE_NUMBER_FLAG_SIGNED);fields.addView(field);}fields.addView(name);new AlertDialog.Builder(c).setTitle("Weather coordinates").setView(fields).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{try{select(Double.parseDouble(lat.getText().toString().trim()),Double.parseDouble(lon.getText().toString().trim()),name.getText().toString().trim().isEmpty()?"Selected location":name.getText().toString().trim());}catch(Exception e){Toast.makeText(c,"Enter valid latitude and longitude",Toast.LENGTH_LONG).show();}}).show();}
 void deviceLocation(){if(c.checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED&&c.checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){c.requestPermissions(new String[]{Manifest.permission.ACCESS_COARSE_LOCATION,Manifest.permission.ACCESS_FINE_LOCATION},701);return;}close();manager=c.getSystemService(LocationManager.class);try{Location best=null;for(String provider:manager.getProviders(true)){Location x=manager.getLastKnownLocation(provider);if(x!=null&&System.currentTimeMillis()-x.getTime()<1800000&&(best==null||x.getTime()>best.getTime()))best=x;}if(best!=null){confirm(best);return;}listener=new LocationListener(){public void onLocationChanged(Location l){close();confirm(l);}public void onStatusChanged(String p,int s,Bundle b){}public void onProviderEnabled(String p){}public void onProviderDisabled(String p){}};boolean requested=false;for(String provider:manager.getProviders(true)){if(provider.equals(LocationManager.PASSIVE_PROVIDER))continue;try{manager.requestLocationUpdates(provider,0,0,listener,Looper.getMainLooper());requested=true;}catch(SecurityException ignored){}}if(!requested){close();Toast.makeText(c,"Location unavailable; choose city or coordinates",Toast.LENGTH_LONG).show();return;}Toast.makeText(c,"Waiting for location (up to 20 seconds)",Toast.LENGTH_LONG).show();h.postDelayed(()->{close();if(!c.isDestroyed())Toast.makeText(c,"No location fix; choose city or coordinates",Toast.LENGTH_LONG).show();},20000);}catch(Exception e){close();Diagnostics.error("weather_location_unavailable",e);Toast.makeText(c,"Use city or coordinates instead",Toast.LENGTH_LONG).show();}}
 void confirm(Location location){if(c.isFinishing()||c.isDestroyed())return;new AlertDialog.Builder(c).setTitle("Use this location for weather?").setMessage("Device location, accuracy about "+Math.round(location.getAccuracy())+" metres. It is sent to Open-Meteo only for weather requests; it is excluded from diagnostic logs.").setNegativeButton("Cancel",null).setPositiveButton("Use location",(d,w)->select(location.getLatitude(),location.getLongitude(),"Device location")).show();}
 void close(){h.removeCallbacksAndMessages(null);if(manager!=null&&listener!=null)try{manager.removeUpdates(listener);}catch(Exception ignored){}listener=null;}
}
